    getPeriodComparison: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description Array of account prefixed IDs to compare
                     * @example [
                     *       "acc_abc123",
                     *       "acc_def456"
                     *     ]
                     */
                    account_ids: string[];
                    /**
                     * @description First period to compare
                     * @example {
                     *       "start": "2024-01-01",
                     *       "end": "2024-03-31"
                     *     }
                     */
                    period_a: {
                        /**
                         * @description Must be a valid date.
                         * @example 2026-06-09T17:23:29
                         */
                        start: string;
                        /**
                         * @description Must be a valid date. Must be a date after or equal to <code>period_a.start</code>.
                         * @example 2109-11-18
                         */
                        end: string;
                    };
                    /**
                     * @description Second period to compare
                     * @example {
                     *       "start": "2024-04-01",
                     *       "end": "2024-06-30"
                     *     }
                     */
                    period_b: {
                        /**
                         * @description Must be a valid date.
                         * @example 2026-06-09T17:23:29
                         */
                        start: string;
                        /**
                         * @description Must be a valid date. Must be a date after or equal to <code>period_b.start</code>.
                         * @example 2045-11-08
                         */
                        end: string;
                    };
                    /**
                     * @description Comparison granularity
                     * @example months
                     * @enum {string}
                     */
                    granularity?: "months" | "quarters" | "half_years" | "years";
                    /**
                     * @description The statistic type to compare
                     * @example totalEarnings
                     * @enum {string}
                     */
                    stat_type?: "totalEarnings" | "subscriptions" | "posts" | "messages" | "tips" | "streams";
                };
            };
        };
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        summary?: {
                            /** @example 15000 */
                            period_a_total?: number;
                            /** @example 18000 */
                            period_b_total?: number;
                            /** @example 3000 */
                            change?: number;
                            /** @example 20 */
                            change_percentage?: number;
                        };
                        /** @example [] */
                        breakdown?: unknown[];
                        /** @example [] */
                        chart_data?: unknown[];
                        /** @example Q1 2024 */
                        period_a_label?: string;
                        /** @example Q2 2024 */
                        period_b_label?: string;
                    };
                };
            };
        };
    };
