    listChargebacks: {
        parameters: {
            query?: {
                /**
                 * @description The start date for the chargebacks. Keep empty to get all.
                 * @example 2025-01-01 00:00:00
                 */
                start_date?: string;
                /**
                 * @description The end date for the chargebacks. Keep empty to get all.
                 * @example 2025-03-31 23:59:59
                 */
                end_date?: string;
                /**
                 * @description Number of chargebacks to return (1-100). Default = 10
                 * @example 50
                 */
                limit?: string | null;
                /**
                 * @description Number of chargebacks to skip, used for pagination.
                 * @example 0
                 */
                offset?: string | null;
            };
            header?: never;
            path: {
                /**
                 * @description The Account ID
                 * @example acct_XXXXXXXXXXXXXXX
                 */
                account: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /**
                             * @example [
                             *       {
                             *         "id": 0,
                             *         "createdAt": "2025-01-01T00:00:00+00:00",
                             *         "paymentType": "tips",
                             *         "payment": {
                             *           "amount": 12.34,
                             *           "vatAmount": 0,
                             *           "taxAmount": 0,
                             *           "mediaTaxAmount": 0,
                             *           "net": 12.34,
                             *           "fee": 5,
                             *           "createdAt": "2025-01-01T00:00:00+00:00",
                             *           "currency": "USD",
                             *           "description": "Tip from <a href=\"https://onlyfans.com/username\">Name</a>",
                             *           "status": "undo",
                             *           "user": {
                             *             "view": "t",
                             *             "id": 123,
                             *             "name": "Name",
                             *             "username": "username",
                             *             "isVerified": false,
                             *             "avatar": null,
                             *             "avatarThumbs": null
                             *           },
                             *           "payoutPendingDays": 7,
                             *           "id": "abc123"
                             *         }
                             *       }
                             *     ]
                             */
                            list?: {
                                /** @example 0 */
                                id?: number;
                                /** @example 2025-01-01T00:00:00+00:00 */
                                createdAt?: string;
                                /** @example tips */
                                paymentType?: string;
                                payment?: {
                                    /** @example 12.34 */
                                    amount?: number;
                                    /** @example 0 */
                                    vatAmount?: number;
                                    /** @example 0 */
                                    taxAmount?: number;
                                    /** @example 0 */
                                    mediaTaxAmount?: number;
                                    /** @example 12.34 */
                                    net?: number;
                                    /** @example 5 */
                                    fee?: number;
                                    /** @example 2025-01-01T00:00:00+00:00 */
                                    createdAt?: string;
                                    /** @example USD */
                                    currency?: string;
                                    /** @example Tip from <a href="https://onlyfans.com/username">Name</a> */
                                    description?: string;
                                    /** @example undo */
                                    status?: string;
                                    user?: {
                                        /** @example t */
                                        view?: string;
                                        /** @example 123 */
                                        id?: number;
                                        /** @example Name */
                                        name?: string;
                                        /** @example username */
                                        username?: string;
                                        /** @example false */
                                        isVerified?: boolean;
                                        /** @example null */
                                        avatar?: string | null;
                                        /** @example null */
                                        avatarThumbs?: string | null;
                                    };
                                    /** @example 7 */
                                    payoutPendingDays?: number;
                                    /** @example abc123 */
                                    id?: string;
                                };
                            }[];
                            /** @example 123 */
                            marker?: number;
                        };
                        _meta?: {
                            _credits?: {
                                /** @example 1 */
                                used?: number;
                                /** @example 999964322 */
                                balance?: number;
                                /** @example Always */
                                note?: string;
                            };
                            _cache?: {
                                /** @example false */
                                is_cached?: boolean;
                                /** @example Cache disabled for this endpoint */
                                note?: string;
                            };
                            _rate_limits?: {
                                /** @example 1000 */
                                limit_minute?: number;
                                /** @example 50000 */
                                limit_day?: number;
                                /** @example 999 */
                                remaining_minute?: number;
                                /** @example 49994 */
                                remaining_day?: number;
                            };
                        };
                    };
                };
            };
        };
    };
