    uploadMediaToTheOnlyFansCDN: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description The Account ID
                 * @example acct_XXXXXXXXXXXXXXX
                 */
                account: string;
            };
            cookie?: never;
        };
        requestBody?: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description The file to upload. Required if `file_url` is not provided. Maximum file size: 100 MB (limited by Cloudflare).
                     */
                    file?: string;
                    /**
                     * @description A URL to download the file from. Required if `file` is not provided. Maximum file size depends on the subscription configuration.
                     * @example https://example.com/media/photo.jpg
                     */
                    file_url?: string;
                    /**
                     * @description Set to `true` to process uploads in the background. Returns a `polling_url` to check status. Recommended for large files.
                     * @example true
                     */
                    async?: boolean;
                    /**
                     * @description Set to `avatar` if this file will be used as a profile picture, `header` for a profile banner, or keep empty if this file will be for anything else.
                     * @example avatar
                     * @enum {string}
                     */
                    type?: "default" | "avatar" | "header";
                };
            };
        };
        responses: {
            /** @description Synchronous upload (default) */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example ofapi_media_abc123def456abc123def456abc123de */
                        prefixed_id?: string;
                        /** @example photo.jpg */
                        file_name?: string;
                        /** @example abc123def456abc123de */
                        processId?: string;
                        /** @example convert3.onlyfans.com */
                        host?: string;
                        /** @example https://of2transcoder.s3.amazonaws.com/upload/00000000-0000-0000-0000-000000000000/000000000000/photo.jpg */
                        sourceUrl?: string;
                        /** @example xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx... */
                        extra?: string;
                        additional?: {
                            /** @example 123456789 */
                            user?: string;
                        };
                        /**
                         * @example [
                         *       {
                         *         "id": 1,
                         *         "url": "https://cdn2.onlyfans.com/files/0/00/00000000000000000000000000000000/300x544_00000000000000000000000000000000.jpg"
                         *       }
                         *     ]
                         */
                        thumbs?: {
                            /** @example 1 */
                            id?: number;
                            /** @example https://cdn2.onlyfans.com/files/0/00/00000000000000000000000000000000/300x544_00000000000000000000000000000000.jpg */
                            url?: string;
                        }[];
                        /** @example Maximum file size is 1 GB. Need higher limits? Contact us for enterprise options. */
                        note?: string;
                    };
                };
            };
            /** @description Async upload (async=true) */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example pending */
                        status?: string;
                        /** @example ofapi_media_abc123def456abc123def456abc123de */
                        prefixed_id?: string;
                        /** @example https://app.onlyfansapi.com/api/acct_abc123def456/media/uploads/ofapi_media_abc123def456abc123def456abc123de/status */
                        polling_url?: string;
                    };
                };
            };
        };
    };
