                            /**
                             * @example [
                             *       {
                             *         "id": 1,
                             *         "url": "https://cdn2.onlyfans.com/files/0/00/00000000000000000000000000000000/300x544_00000000000000000000000000000000.jpg"
                             *       }
                             *     ]
                             */
