    uploadMediaToVault: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description The Account ID
                 * @example acct_XXXXXXXXXXXXXXX
                 */
                account: string;
            };
            cookie?: never;
        };
        requestBody?: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description The file to upload. Required if `file_url` is not provided. Maximum file size: 100 MB (limited by Cloudflare).
                     */
                    file?: string;
                    /**
                     * @description A URL to download the file from. Required if `file` is not provided. Maximum file size depends on the subscription configuration.
                     * @example https://example.com/media/photo.jpg
                     */
                    file_url?: string;
                    /**
                     * @description Set to `true` to process uploads in the background. Returns a `polling_url` to check status. Recommended for large files.
                     * @example true
                     */
                    async?: boolean;
                };
            };
        };
        responses: {
            /** @description Synchronous upload (default) */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /** @example 1234567890 */
                            id?: number;
                            /** @example photo */
                            type?: string;
                            /** @example false */
                            convertedToVideo?: boolean;
                            /** @example true */
                            canView?: boolean;
                            /** @example false */
                            hasError?: boolean;
                            /** @example 2026-04-03T16:16:36+00:00 */
                            createdAt?: string;
                            /** @example false */
                            isReady?: boolean;
                            files?: {
                                full?: {
                                    /** @example null */
                                    url?: string | null;
                                    /** @example 0 */
                                    width?: number;
                                    /** @example 0 */
                                    height?: number;
                                    /** @example 0 */
                                    size?: number;
                                    /** @example [] */
                                    sources?: unknown[];
                                };
                                /** @example null */
                                thumb?: string | null;
                                /** @example null */
                                preview?: string | null;
                                /** @example null */
                                squarePreview?: string | null;
                            };
                            /** @example 0 */
                            duration?: number;
                            /** @example [] */
                            releaseForms?: unknown[];
                            /** @example false */
                            hasCustomPreview?: boolean;
                        };
                        _meta?: {
                            _credits?: {
                                /** @example 3 */
                                used?: number;
                                /** @example 636132 */
                                balance?: number;
                                /** @example Always */
                                note?: string;
                            };
                            _cache?: {
                                /** @example false */
                                is_cached?: boolean;
                                /** @example Cache disabled for this endpoint */
                                note?: string;
                            };
                            _rate_limits?: {
                                /** @example 5000 */
                                limit_minute?: number;
                                /** @example null */
                                limit_day?: string | null;
                                /** @example 4999 */
                                remaining_minute?: number;
                                /** @example null */
                                remaining_day?: string | null;
                            };
                        };
                    };
                };
            };
            /** @description Async upload (async=true) */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example pending */
                        status?: string;
                        /** @example ofapi_media_abc123def456abc123def456abc123de */
                        prefixed_id?: string;
                        /** @example https://app.onlyfansapi.com/api/acct_abc123def456/media/uploads/ofapi_media_abc123def456abc123def456abc123de/status */
                        polling_url?: string;
                    };
                };
            };
        };
    };
