    updatePost: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description The Account ID
                 * @example acct_XXXXXXXXXXXXXXX
                 */
                account: string;
                /**
                 * @description The ID of the post
                 * @example 1234567890
                 */
                post_id: number;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description The post text content
                     * @example Hello!
                     */
                    text: string;
                    /**
                     * @description Array of OF label IDs. Refer to our `/posts/labels` endpoint.
                     * @example [
                     *       123
                     *     ]
                     */
                    labelIds?: string;
                    /**
                     * @description Price for paid content (0 or between 3-100). In case this is not zero, **mediaFiles** is required
                     * @example 10
                     */
                    price?: number;
                    /**
                     * @description Array of OFAPI `ofapi_media_` IDs, or OF media IDs
                     * @example [
                     *       "ofapi_media_abc123",
                     *       "1234567890"
                     *     ]
                     */
                    mediaFiles?: string;
                    /**
                     * @description Array OnlyFans creator user IDs to tag in your post
                     * @example [
                     *       123
                     *     ]
                     */
                    rfTag?: string;
                    /**
                     * @description Number of days after which the post will expire. Between 1 and 30 days. Keep empty for no expiration.
                     * @example 3
                     */
                    expireDays?: number;
                    /**
                     * @description Schedule your post in the future (UTC timezone).
                     * @example 2025-01-01T00:00:00.000Z
                     */
                    scheduledDate?: string;
                    /**
                     * @description Add your post to the "Saved for later" queue.
                     * @example true
                     */
                    saveForLater?: boolean;
                    /**
                     * @description Add a fundraising target to your post. If present, value must be at least 10.
                     * @example 30
                     */
                    fundRaisingTargetAmount?: number;
                    /**
                     * @description Specify which tip amounts will be listed under the fundraising card. Required with `fundRaisingTargetAmount`, and you must provide at least 1 option. Array items cannot be higher than the `fundRaisingTargetAmount`.
                     * @example [
                     *       5,
                     *       10,
                     *       15
                     *     ]
                     */
                    fundRaisingTipsPresets?: string[];
                    /**
                     * @description Include a poll or quiz within your post.
                     * @example poll
                     * @enum {string}
                     */
                    votingType?: "poll" | "quiz";
                    /**
                     * @description The due date (in days) of your poll/quiz. Can be 1, 3, 7 or 30 days. Can only be filled with `votingType`.
                     * @example 3
                     */
                    votingDue?: number;
                    /**
                     * @description The options of your poll/quiz. Required with `votingType`.
                     * @example [
                     *       "First option",
                     *       "Second option"
                     *     ]
                     */
                    votingOptions?: string[];
                    /**
                     * @description The array key of your quiz' correct answer. Required when `votingType` is "quiz". Keep in mind that arrays start at `0`
                     * @example 0
                     */
                    votingCorrectIndex?: number;
                };
            };
        };
        responses: {
            /** @description Success */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
        };
    };
