    getTrackingLink: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description The Account ID
                 * @example acct_XXXXXXXXXXXXXXX
                 */
                account: string;
                /**
                 * @description The ID of the tracking link.
                 * @example rerum
                 */
                tracking_link_id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /** @example 123456 */
                            id?: number;
                            /** @example 123 */
                            campaignCode?: number;
                            /** @example Example Campaign - IG Bio SFS */
                            campaignName?: string;
                            /** @example https://onlyfans.com/USERNAME/c123 */
                            campaignUrl?: string;
                            /** @example null */
                            subscribersCount?: string | null;
                            /** @example null */
                            clicksCount?: string | null;
                            /** @example 2025-01-01T00:00:00+00:00 */
                            createdAt?: string;
                            /** @example null */
                            endDate?: string | null;
                            /**
                             * @example [
                             *       "Instagram",
                             *       "Twitter"
                             *     ]
                             */
                            tags?: string[];
                            revenue?: {
                                /** @example 20 */
                                total?: number;
                                /** @example 2 */
                                revenuePerSubscriber?: number;
                                /** @example 0.2 */
                                revenuePerClick?: number;
                                /** @example 1 */
                                spendersCount?: number;
                                /** @example 2025-01-01T00:00:00+00:00 */
                                calculatedAt?: string;
                                /** @example false */
                                isLoading?: boolean;
                            };
                            cost?: {
                                /** @example null */
                                inputMode?: string | null;
                                /** @example null */
                                inputValue?: string | null;
                                /** @example null */
                                perSub?: string | null;
                                /** @example null */
                                perClick?: string | null;
                                /** @example null */
                                perPromo?: string | null;
                                /** @example 0 */
                                subscriberSourceCount?: number;
                                /** @example 0 */
                                clickSourceCount?: number;
                            };
                            links?: {
                                related?: {
                                    /** @example http://ofapi.test/api/acct_XXXXXXXX/tracking-links/123456/subscribers */
                                    subscribers?: string;
                                    /** @example http://ofapi.test/api/acct_XXXXXXXX/tracking-links/123456/spenders */
                                    spenders?: string;
                                };
                            };
                        };
                        _meta?: {
                            _credits?: {
                                /** @example 1 */
                                used?: number;
                                /** @example 7095558 */
                                balance?: number;
                                /** @example Always */
                                note?: string;
                            };
                            _cache?: {
                                /** @example false */
                                is_cached?: boolean;
                                /** @example Cache disabled for this endpoint */
                                note?: string;
                            };
                            _rate_limits?: {
                                /** @example 5000 */
                                limit_minute?: number;
                                /** @example null */
                                limit_day?: string | null;
                                /** @example 4998 */
                                remaining_minute?: number;
                                /** @example null */
                                remaining_day?: string | null;
                                /** @example We have decided to remove our daily rate limits. Please remove any references to these in your integrations. */
                                notice?: string;
                            };
                        };
                    };
                };
            };
        };
    };
