    listTransactions: {
        parameters: {
            query?: {
                /**
                 * @description The number of transactions to return. Recommended: `10`
                 * @example 10
                 */
                limit?: string;
                /**
                 * @description The start date for transactions list. Default: `-30days`
                 * @example 2025-01-01 00:00:00, -30days
                 */
                startDate?: string;
                /**
                 * @description The marker used for pagination. Default: `null`
                 * @example 1739155047
                 */
                marker?: string;
                /**
                 * @description Filter by transaction type. Options: `subscribes`, `tips`, `post`, `chat_messages`, `stream`
                 * @example tips
                 */
                type?: string;
                /**
                 * @description Filter tips by source. Only applies when `type=tips`. Options: `profile`, `post_all`, `chat`, `stream`, `story`
                 * @example post_all
                 */
                tipsSource?: string;
            };
            header?: never;
            path: {
                /**
                 * @description The Account ID
                 * @example acct_XXXXXXXXXXXXXXX
                 */
                account: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Success */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /**
                             * @example [
                             *       {
                             *         "amount": 19.99,
                             *         "vatAmount": 0,
                             *         "taxAmount": 0,
                             *         "net": 15.99,
                             *         "fee": 4,
                             *         "createdAt": "2025-02-10T02:51:22+00:00",
                             *         "currency": "USD",
                             *         "description": "Payment for message from <a href=\"https://onlyfans.com/XXXXXXXX\">XXXXXXXX</a>",
                             *         "status": "loading",
                             *         "user": {
                             *           "view": "t",
                             *           "id": 123123123,
                             *           "name": "Michael XXXXXXXX",
                             *           "username": "u123123123",
                             *           "isVerified": false,
                             *           "avatar": "https://public.onlyfans.com/files/XXXXXXXXXX.jpg",
                             *           "avatarThumbs": {
                             *             "c50": "https://thumbs.onlyfans.com/public/files/thumbs/c50/XXXXXXXXXX.jpg",
                             *             "c144": "https://thumbs.onlyfans.com/public/files/thumbs/c144/XXXXXXXXXX.jpg"
                             *           }
                             *         },
                             *         "payoutPendingDays": 7,
                             *         "id": "5XXXXXXXXXaa1aXXXXXXXXXXX",
                             *         "type": "message"
                             *       }
                             *     ]
                             */
                            list?: {
                                /** @example 19.99 */
                                amount?: number;
                                /** @example 0 */
                                vatAmount?: number;
                                /** @example 0 */
                                taxAmount?: number;
                                /** @example 15.99 */
                                net?: number;
                                /** @example 4 */
                                fee?: number;
                                /** @example 2025-02-10T02:51:22+00:00 */
                                createdAt?: string;
                                /** @example USD */
                                currency?: string;
                                /** @example Payment for message from <a href="https://onlyfans.com/XXXXXXXX">XXXXXXXX</a> */
                                description?: string;
                                /** @example loading */
                                status?: string;
                                user?: {
                                    /** @example t */
                                    view?: string;
                                    /** @example 123123123 */
                                    id?: number;
                                    /** @example Michael XXXXXXXX */
                                    name?: string;
                                    /** @example u123123123 */
                                    username?: string;
                                    /** @example false */
                                    isVerified?: boolean;
                                    /** @example https://public.onlyfans.com/files/XXXXXXXXXX.jpg */
                                    avatar?: string;
                                    avatarThumbs?: {
                                        /** @example https://thumbs.onlyfans.com/public/files/thumbs/c50/XXXXXXXXXX.jpg */
                                        c50?: string;
                                        /** @example https://thumbs.onlyfans.com/public/files/thumbs/c144/XXXXXXXXXX.jpg */
                                        c144?: string;
                                    };
                                };
                                /** @example 7 */
                                payoutPendingDays?: number;
                                /** @example 5XXXXXXXXXaa1aXXXXXXXXXXX */
                                id?: string;
                                /** @example message */
                                type?: string;
                            }[];
                            /** @example 1739156703 */
                            marker?: number;
                            /** @example true */
                            hasMore?: boolean;
                            /** @example 1739155047 */
                            nextMarker?: number;
                        };
                        _pagination?: {
                            /** @example https://app.onlyfansapi.com/api/acct_XXXXXXXX/transactions?startDate=-30days&marker=1739155047& */
                            next_page?: string;
                        };
                        _meta?: {
                            _credits?: {
                                /** @example 1 */
                                used?: number;
                                /** @example 34 */
                                balance?: number;
                                /** @example Always */
                                note?: string;
                            };
                            _cache?: {
                                /** @example false */
                                is_cached?: boolean;
                                /** @example Cache disabled for this endpoint */
                                note?: string;
                            };
                            _rate_limits?: {
                                /** @example 1000 */
                                limit_minute?: number;
                                /** @example 50000 */
                                limit_day?: number;
                                /** @example 990 */
                                remaining_minute?: number;
                                /** @example 49977 */
                                remaining_day?: number;
                            };
                        };
                    };
                };
            };
        };
    };
